1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Customer = {
8	  yearsWithMHPCO: number;
9	};
10	
11	export type Damage = {
12	  itemType: string;
13	  amount: number;
14	};
15	
16	export type Incident = {
17	  cause: string;
18	  damages: Damage[];
19	};
20	
21	export type Step = {
22	  op: string;
23	  items?: Item[];
24	  policy?: number;
25	  incident?: Incident;
26	};
27	
28	export type Scenario = {
29	  customer: Customer;
30	  steps: Step[];
31	};
32	
33	export type QuoteResult = { premium: number };
34	export type ClaimResult = { payout: number; remainingCap: number };
35	
36	export type ScenarioResult = {
37	  results: (QuoteResult | ClaimResult)[];
38	};
39	
40	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	  staff: 80,
44	  potion: 40,
45	  rune: 25,
46	  moonstone: 25,
47	};
48	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
49	  sword: 1000,
50	  amulet: 600,
51	  staff: 800,
52	  potion: 400,
53	  rune: 250,
54	  moonstone: 250,
55	};
56	const DEDUCTIBLE = 100;
57	const CAP_MULTIPLE = 2;
58	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
59	const CURSE_SURCHARGE_PERCENT = 50;
60	const HIGH_ENCHANTMENT_THRESHOLD = 5;
61	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
62	const LOYALTY_THRESHOLD_YEARS = 2;
63	const LOYALTY_DISCOUNT_PERCENT = 20;
64	const FOLLOWUP_DISCOUNT_PERCENT = 15;
65	const PROCESSING_FEE = 5;
66	
67	const percentOf = (amount: number, percent: number): number =>
68	  (amount * percent) / 100;
69	
70	/**
71	 * Premiums round UP — the MHPCO's favour on money coming IN. Payouts will need
72	 * the opposite direction, so this deliberately names the premium case only
73	 * rather than a general "in the MHPCO's favour" rounding.
74	 */
75	const roundPremiumUp = (premium: number): number => Math.ceil(premium);
76	
77	const BLOCK_SIZE = 3;
78	const BLOCK_BASE_PREMIUM = 60;
79	
80	/** Counts of items of the same type — "alike" in the MHPCO's terms. */
81	const countAlikeItems = (items: Item[]): Map<string, number> =>
82	  items.reduce(
83	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
84	    new Map<string, number>(),
85	  );
86	
87	const formsBuildingBlock = (count: number): boolean => count === BLOCK_SIZE;
88	
89	const basePremiumForAlikeItems = (type: string, count: number): number =>
90	  formsBuildingBlock(count)
91	    ? BLOCK_BASE_PREMIUM
92	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
93	
94	const policyBasePremium = (items: Item[]): number =>
95	  [...countAlikeItems(items)].reduce(
96	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
97	    0,
98	  );
99	
100	const itemBasePremium = (item: Item): number =>
101	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
102	
103	const isHighlyEnchanted = (item: Item): boolean =>
104	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
105	
106	/** Item-specific surcharges stack additively. */
107	const itemSurchargePercent = (item: Item): number =>
108	  (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
109	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
110	
111	/**
112	 * Item-specific modifiers are percentages of the AFFECTED ITEM's own base
113	 * premium — unlike policy-wide modifiers, which apply to the policy base.
114	 */
115	const totalItemSurcharges = (items: Item[]): number =>
116	  items.reduce(
117	    (total, item) =>
118	      total + percentOf(itemBasePremium(item), itemSurchargePercent(item)),
119	    0,
120	  );
121	
122	const isLongStanding = (customer: Customer): boolean =>
123	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
124	
125	/**
126	 * The net of all policy-wide percentages. Policy-wide modifiers are
127	 * percentages of the POLICY base premium — unlike item-specific modifiers,
128	 * which apply to the affected item's own base. The net is negative when the
129	 * discounts outweigh the surcharges: a long-standing customer nets -10 %.
130	 */
131	const netPolicyAdjustmentPercent = (
132	  customer: Customer,
133	  precedingSteps: number,
134	): number =>
135	  FIRST_INSURANCE_SURCHARGE_PERCENT -
136	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_PERCENT : 0) -
137	  // The follow-up discount is owed on every quote after the customer's FIRST
138	  // QUOTE, but what we have here is a count of preceding STEPS. The two
139	  // coincide only because every step exercised so far is a quote; once claim
140	  // steps arrive, [quote, claim, quote] will wrongly discount the third step
141	  // as a second follow-up. No test forces the distinction yet.
142	  (precedingSteps > 0 ? FOLLOWUP_DISCOUNT_PERCENT : 0);
143	
144	const policyAdjustment = (
145	  policyBase: number,
146	  customer: Customer,
147	  precedingSteps: number,
148	): number =>
149	  percentOf(policyBase, netPolicyAdjustmentPercent(customer, precedingSteps));
150	
151	const quotePremium = (
152	  items: Item[],
153	  customer: Customer,
154	  precedingSteps: number,
155	): number => {
156	  const basePremium = policyBasePremium(items);
157	  return roundPremiumUp(
158	    basePremium +
159	      totalItemSurcharges(items) +
160	      policyAdjustment(basePremium, customer, precedingSteps) +
161	      PROCESSING_FEE,
162	  );
163	};
164	
165	const roundPayoutDown = (payout: number): number => Math.floor(payout);
166	
167	const insuranceSum = (items: Item[]): number =>
168	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_ITEM_TYPE[item.type], 0);
169	
170	/** The deductible applies once per damaged item, not once per incident. */
171	const payoutFor = (incident: Incident): number =>
172	  incident.damages.reduce(
173	    (total, damage) => total + damage.amount - DEDUCTIBLE,
174	    0,
175	  );
176	
177	const claimResult = (step: Step, scenario: Scenario): ClaimResult => {
178	  const policyItems = scenario.steps[step.policy ?? 0].items ?? [];
179	  const cap = CAP_MULTIPLE * insuranceSum(policyItems);
180	  const payout = roundPayoutDown(payoutFor(step.incident!));
181	  return { payout, remainingCap: cap - payout };
182	};
183	
184	export const runScenario = (scenario: Scenario): ScenarioResult => ({
185	  results: scenario.steps.map((step, precedingSteps) =>
186	    step.op === "claim"
187	      ? claimResult(step, scenario)
188	      : {
189	          premium: quotePremium(
190	            step.items ?? [],
191	            scenario.customer,
192	            precedingSteps,
193	          ),
194	        },
195	  ),
196	});
